def _bool_fact(facts, name):
    v = facts.get(name)
    if isinstance(v, bool):
        return v
    return None

def _number_fact(facts, name):
    v = facts.get(name)
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    return None

def _actor(question):
    m = re.search(r"\bto\s+([A-Z][A-Za-z'-]*)", question)
    if m:
        return m.group(1)
    m = re.search(r"\b([A-Z][A-Za-z'-]*)'s\s+additional", question)
    if m:
        return m.group(1)
    return "the taxpayer"

def _is_c6a(question):
    return re.search(r"63\s*\(\s*c\s*\)\s*\(\s*6\s*\)\s*\(\s*A\s*\)", question, re.I) is not None

def _is_c3_amount(question):
    cited = re.search(r"63\s*\(\s*c\s*\)\s*\(\s*3\s*\)", question, re.I) is not None
    return cited and "additional standard deduction" in question.casefold()

def _negated(question):
    return re.search(r"\bnot\b|does\s+not|isn't|is\s+unequal", question, re.I) is not None

def _claim_amount(question):
    matches = re.findall(r"\$\s*([0-9][0-9,]*(?:\.[0-9]+)?)", question)
    if not matches:
        m = re.search(r"(?:equal\s+to|equals|is)\s+([0-9][0-9,]*(?:\.[0-9]+)?)", question, re.I)
        if not m:
            return None
        raw = m.group(1)
    else:
        raw = matches[-1]
    raw = raw.replace(",", "")
    if "." in raw:
        return float(raw)
    return int(raw)

def _invert(answer):
    if answer == "Entailment":
        return "Contradiction"
    if answer == "Contradiction":
        return "Entailment"
    return "unknown"

def _either_itemizes(taxpayer_itemizes, spouse_itemizes):
    if taxpayer_itemizes is True or spouse_itemizes is True:
        return True
    if taxpayer_itemizes is False and spouse_itemizes is False:
        return False
    return None

def _c6a_applies(facts):
    married = _bool_fact(facts, "married_at_close")
    separate = _bool_fact(facts, "filed_separate_return")
    itemizes = _either_itemizes(_bool_fact(facts, "taxpayer_itemized"), _bool_fact(facts, "spouse_itemized"))
    if married is False or separate is False or itemizes is False:
        return False
    if married is True and separate is True and itemizes is True:
        return True
    return None

def _spouse_exemption_allowed(facts):
    exists = _bool_fact(facts, "spouse_existed_for_exemption")
    joint = _bool_fact(facts, "joint_return_made")
    income = _number_fact(facts, "spouse_gross_income")
    dependent = _bool_fact(facts, "spouse_was_another_taxpayers_dependent")
    if exists is False or joint is True or dependent is True:
        return False
    if income is not None and income != 0:
        return False
    if exists is True and joint is False and income == 0 and dependent is False:
        return True
    return None

def _age_65(facts, field):
    age = _number_fact(facts, field)
    if age is None:
        return None
    return age >= 65

def _and_tri(a, b):
    if a is False or b is False:
        return False
    if a is True and b is True:
        return True
    return None

def _surviving_spouse(facts):
    death = _bool_fact(facts, "spouse_died_in_two_preceding_years")
    home = _bool_fact(facts, "maintained_home_for_dependent_child")
    cost = _bool_fact(facts, "furnished_over_half_household_cost")
    remarried = _bool_fact(facts, "remarried_before_year_end")
    joint_possible = _bool_fact(facts, "joint_return_possible_in_death_year")
    if death is False or home is False or cost is False or remarried is True or joint_possible is False:
        return False
    if death is True and home is True and cost is True and remarried is False and joint_possible is True:
        return True
    return None

def _rate_possibilities(facts):
    married = _bool_fact(facts, "married_at_close")
    surviving = _surviving_spouse(facts)
    rates = set()
    if married is True:
        rates.add(600)
        return rates
    if married is False:
        if surviving is False:
            rates.add(750)
        elif surviving is True:
            rates.add(600)
        else:
            rates.add(600)
            rates.add(750)
        return rates
    rates.add(600)
    if surviving is not True:
        rates.add(750)
    return rates

def _event_possibilities(value):
    if value is True:
        return [1]
    if value is False:
        return [0]
    return [0, 1]

def _possible_event_counts(events):
    counts = set([0])
    for event in events:
        next_counts = set()
        for old in counts:
            for addend in _event_possibilities(event):
                next_counts.add(old + addend)
        counts = next_counts
    return counts

def _possible_additional_amounts(facts):
    exemption = _spouse_exemption_allowed(facts)
    self_aged = _age_65(facts, "taxpayer_age_at_year_end")
    self_blind = _bool_fact(facts, "taxpayer_blind_at_year_end")
    spouse_aged = _and_tri(_age_65(facts, "spouse_age_at_year_end"), exemption)
    spouse_blind = _and_tri(_bool_fact(facts, "spouse_blind_at_relevant_time"), exemption)
    counts = _possible_event_counts([self_aged, self_blind, spouse_aged, spouse_blind])
    totals = set()
    for rate in _rate_possibilities(facts):
        for count in counts:
            totals.add(rate * count)
    return totals

def _missing(facts, names):
    result = []
    for name in names:
        if facts.get(name) is None:
            result.append(name)
    return result

def _c6_plan(actor):
    return {
        "supported": True,
        "fields": {
            "married_at_close": {"type": "boolean", "question": "Was " + actor + " married at the close of the taxable year?"},
            "filed_separate_return": {"type": "boolean", "question": "Did " + actor + " file a separate return for the taxable year?"},
            "taxpayer_itemized": {"type": "boolean", "question": "Did " + actor + " itemize deductions for the taxable year?"},
            "spouse_itemized": {"type": "boolean", "question": "Did " + actor + "'s spouse itemize deductions for the taxable year?"}
        }
    }

def _amount_plan(actor):
    return {
        "supported": True,
        "fields": {
            "married_at_close": {"type": "boolean", "question": "Was " + actor + " married at the close of the taxable year?"},
            "spouse_died_in_two_preceding_years": {"type": "boolean", "question": "Did " + actor + "'s spouse die during either of the two years immediately preceding the taxable year?"},
            "maintained_home_for_dependent_child": {"type": "boolean", "question": "Did " + actor + " maintain a home that was the taxable-year principal abode of a dependent son, stepson, daughter, or stepdaughter?"},
            "furnished_over_half_household_cost": {"type": "boolean", "question": "Did " + actor + " furnish over half the cost of maintaining that household during the taxable year?"},
            "remarried_before_year_end": {"type": "boolean", "question": "Had " + actor + " remarried before the close of the taxable year?"},
            "joint_return_possible_in_death_year": {"type": "boolean", "question": "Could " + actor + " and the deceased spouse have made a joint return for the taxable year in which the spouse died?"},
            "taxpayer_age_at_year_end": {"type": "integer", "question": "What was " + actor + "'s age at the close of the taxable year?"},
            "taxpayer_blind_at_year_end": {"type": "boolean", "question": "Was " + actor + " blind at the close of the taxable year?"},
            "spouse_existed_for_exemption": {"type": "boolean", "question": "Did " + actor + " have a spouse during the taxable year for whom the spouse facts below are stated?"},
            "spouse_age_at_year_end": {"type": "integer", "question": "What was the spouse's age at the close of the taxable year?"},
            "spouse_blind_at_relevant_time": {"type": "boolean", "question": "Was the spouse blind at the close of the taxable year, or at death if the spouse died during that year?"},
            "joint_return_made": {"type": "boolean", "question": "Did " + actor + " and the spouse make a joint return?"},
            "spouse_gross_income": {"type": "number", "question": "How much gross income did the spouse have for the relevant calendar year?"},
            "spouse_was_another_taxpayers_dependent": {"type": "boolean", "question": "Was the spouse the dependent of another taxpayer for the relevant calendar year?"}
        }
    }

def apply(inputs, premises):
    phase = inputs.get("phase")
    question = inputs.get("question", "")
    if not isinstance(question, str):
        question = ""
    actor = _actor(question)
    if phase == "plan":
        if _is_c6a(question):
            return _c6_plan(actor)
        if _is_c3_amount(question):
            return _amount_plan(actor)
        return {"supported": False, "fields": {}}
    if phase != "evaluate":
        return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["unsupported phase"]}
    facts = inputs.get("facts", {})
    if not isinstance(facts, dict):
        facts = {}
    if _is_c6a(question):
        result = _c6a_applies(facts)
        if result is None:
            deps = _missing(facts, ["married_at_close", "filed_separate_return", "taxpayer_itemized", "spouse_itemized"])
            return {"answer": "unknown", "used_rule_ids": ["R63_C6_A"], "open_dependencies": deps}
        answer = "Entailment" if result else "Contradiction"
        if _negated(question):
            answer = _invert(answer)
        return {"answer": answer, "used_rule_ids": ["R63_C6_A"], "open_dependencies": []}
    if _is_c3_amount(question):
        claimed = _claim_amount(question)
        if claimed is None:
            return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["claimed monetary amount"]}
        totals = _possible_additional_amounts(facts)
        if claimed not in totals:
            answer = "Contradiction"
        elif len(totals) == 1:
            answer = "Entailment"
        else:
            deps = _missing(facts, ["married_at_close", "spouse_died_in_two_preceding_years", "maintained_home_for_dependent_child", "furnished_over_half_household_cost", "remarried_before_year_end", "joint_return_possible_in_death_year", "taxpayer_age_at_year_end", "taxpayer_blind_at_year_end", "spouse_existed_for_exemption", "spouse_age_at_year_end", "spouse_blind_at_relevant_time", "joint_return_made", "spouse_gross_income", "spouse_was_another_taxpayers_dependent"])
            return {"answer": "unknown", "used_rule_ids": ["R63_C3", "R63_F1", "R63_F2", "R63_F3", "R151_B", "R2_SURVIVING"], "open_dependencies": deps}
        if _negated(question):
            answer = _invert(answer)
        return {"answer": answer, "used_rule_ids": ["R63_C3", "R63_F1", "R63_F2", "R63_F3", "R151_B", "R2_SURVIVING"], "open_dependencies": []}
    return {"answer": "unknown", "used_rule_ids": [], "open_dependencies": ["unsupported statutory claim format"]}
